# Migrate AI SDK 6.x to 7.0
## [AI SDK Core](https://ai-sdk.dev/docs/migration-guides/migration-guide-7-0#ai-sdk-core)
### [Streaming and Include Options](https://ai-sdk.dev/docs/migration-guides/migration-guide-7-0#streaming-and-include-options)
#### [`StreamTextResult.fullStream` Renamed to `stream`](https://ai-sdk.dev/docs/migration-guides/migration-guide-7-0#streamtextresultfullstream-renamed-to-stream)
```
const result = streamText({
  model: yourModel,
  prompt: 'Hello!',
});

for await (const part of result.fullStream) {
  console.log(part);
}
```

```
const result = streamText({
  model: yourModel,
  prompt: 'Hello!',
});

for await (const part of result.stream) {
  console.log(part);
}
```

#### [`streamText``onChunk` Receives All Stream Parts](https://ai-sdk.dev/docs/migration-guides/migration-guide-7-0#streamtext-onchunk-receives-all-stream-parts)
```
const result = streamText({
  model: yourModel,
  prompt: 'Hello',
  onChunk({ chunk }) {
    if (chunk.type === 'text-delta') {
      console.log(chunk.text);
    }
  },
});
```

#### [Move `includeRawChunks` to `include.rawChunks`](https://ai-sdk.dev/docs/migration-guides/migration-guide-7-0#move-includerawchunks-to-includerawchunks)
```
const result = streamText({
  model: yourModel,
  prompt: 'Hello',
  includeRawChunks: true,
});
```

```
const result = streamText({
  model: yourModel,
  prompt: 'Hello',
  include: {
    rawChunks: true,
  },
});
```

#### [Request and Response Bodies Are Excluded by Default](https://ai-sdk.dev/docs/migration-guides/migration-guide-7-0#request-and-response-bodies-are-excluded-by-default)
```
const result = await generateText({
  model: yourModel,
  prompt: 'Hello',
  include: {
    requestBody: true,
    responseBody: true,
  },
});
```

```
const result = streamText({
  model: yourModel,
  prompt: 'Hello',
  include: {
    requestBody: true,
  },
});
```

### [Stream Response Helpers](https://ai-sdk.dev/docs/migration-guides/migration-guide-7-0#stream-response-helpers)
#### [`streamText` Response Helpers Deprecated — Use Stateless Helpers](https://ai-sdk.dev/docs/migration-guides/migration-guide-7-0#streamtext-response-helpers-deprecated--use-stateless-helpers)
```
const result = streamText({ model, prompt });

const uiStream = result.toUIMessageStream({
  originalMessages,
  generateMessageId,
  onFinish,
});
```

## The migration is really about context boundaries [#](https://www.developersdigest.tech/blog/vercel-ai-sdk-7-production-agents#the-migration-is-really-about-context-boundaries)
```ts
const weather = tool({
  inputSchema: z.object({
    location: z.string(),
  }),
  contextSchema: z.object({
    apiKey: z.string(),
  }),
  execute: async ({ location }, { context: { apiKey } }) => {
    return getWeather(location, apiKey);
  },
});

const result = await generateText({
  model,
  tools: { weather },
  prompt: "Will it rain in Toronto tomorrow?",
  runtimeContext: {
    requestId: "req_123",
    tenantId: "tenant_456",
  },
  toolsContext: {
    weather: {
      apiKey: process.env.WEATHER_API_KEY!,
    },
  },
});
```

## Streaming [Direct link to Streaming](https://mastra.ai/docs/v0/frameworks/agentic-uis/ai-sdk#streaming)
```bash
yarn add @mastra/ai-sdk
```

### Custom UI [Direct link to Custom UI](https://mastra.ai/docs/v0/frameworks/agentic-uis/ai-sdk#custom-ui)
```typescript
"use client";

import { useChat } from "@ai-sdk/react";
import { AgentTool } from '../ui/agent-tool';
import { DefaultChatTransport } from 'ai';
import type { AgentDataPart } from "@mastra/ai-sdk";

export default function Page() {
  const { messages } = useChat({
    transport: new DefaultChatTransport({
    api: 'http://localhost:4111/chat',
    }),
  });

  return (
    <div>
      {messages.map((message) => (
        <div key={message.id}>
          {message.parts.map((part, i) => {
            switch (part.type) {
              case 'data-tool-agent':
                return (
                  <AgentTool {...part.data as AgentDataPart} key={`${message.id}-${i}`} />
                );
              default:
                return null;
            }
          })}
        </div>
      ))}
    </div>
  );
}
```

```typescript
import { Tool, ToolContent, ToolHeader, ToolOutput } from "../ai-elements/tool";
import type { AgentDataPart } from "@mastra/ai-sdk";

export const AgentTool = ({ id, text, status }: AgentDataPart) => {
  return (
    <Tool>
      <ToolHeader
        type={`${id}`}
        state={status === 'finished' ? 'output-available' : 'input-available'}
      />
      <ToolContent>
        <ToolOutput output={text} />
      </ToolContent>
    </Tool>
  );
};
```

### Stream Transformations [Direct link to Stream Transformations](https://mastra.ai/docs/v0/frameworks/agentic-uis/ai-sdk#stream-transformations)
```typescript
import { mastra } from "../../mastra";
import { createUIMessageStream, createUIMessageStreamResponse } from "ai";
import { toAISdkFormat } from "@mastra/ai-sdk";

export async function POST(req: Request) {
  const { messages } = await req.json();
  const myAgent = mastra.getAgent("weatherAgent");
  const stream = await myAgent.stream(messages);

  // Transform stream into AI SDK format and create UI messages stream
  const uiMessageStream = createUIMessageStream({
    execute: async ({ writer }) => {
      for await (const part of toAISdkFormat(stream, { from: "agent" })!) {
        writer.write(part);
      }
    },
  });

  // Create a Response that streams the UI message stream to the client
  return createUIMessageStreamResponse({
    stream: uiMessageStream,
  });
}
```

### Client Side Stream Transformations [Direct link to Client Side Stream Transformations](https://mastra.ai/docs/v0/frameworks/agentic-uis/ai-sdk#client-side-stream-transformations)
```typescript
import { createUIMessageStream } from "ai";
import { toAISdkFormat } from "@mastra/ai-sdk";
import type { ChunkType, MastraModelOutput } from "@mastra/core/stream";

// Client SDK agent stream
const response = await agent.stream({
  messages: "What is the weather in Tokyo",
});

const chunkStream: ReadableStream<ChunkType> = new ReadableStream<ChunkType>({
  start(controller) {
    response
      .processDataStream({
        onChunk: async (chunk) => {
          controller.enqueue(chunk as ChunkType);
        },
      })
      .finally(() => controller.close());
  },
});

const uiMessageStream = createUIMessageStream({
  execute: async ({ writer }) => {
    for await (const part of toAISdkFormat(
      chunkStream as unknown as MastraModelOutput,
      { from: "agent" },
    )) {
      writer.write(part);
    }
  },
});

for await (const part of uiMessageStream) {
  console.log(part);
}
```

# Migrate AI SDK 3.4 to 4.0
## [AI SDK Core Changes](https://ai-sdk.dev/docs/migration-guides/migration-guide-4-0#ai-sdk-core-changes)
### [`streamText` returns immediately](https://ai-sdk.dev/docs/migration-guides/migration-guide-4-0#streamtext-returns-immediately)
```
const result = await streamText({
  // ...
});
```

```
const result = streamText({
  // ...
});
```

### [`streamObject` returns immediately](https://ai-sdk.dev/docs/migration-guides/migration-guide-4-0#streamobject-returns-immediately)
```
const result = streamObject({
  // ...
});
```

### [Removed experimental AI function exports](https://ai-sdk.dev/docs/migration-guides/migration-guide-4-0#removed-experimental-ai-function-exports)
```
import { generateText, streamText, generateObject, streamObject } from 'ai';
```

### [Removed AI-stream related methods from `streamText`](https://ai-sdk.dev/docs/migration-guides/migration-guide-4-0#removed-ai-stream-related-methods-from-streamtext)
```
const result = await streamText({
  // ...
});

result.toAIStream();
result.pipeAIStreamToResponse(response);
result.toAIStreamResponse();
```

```
const result = streamText({
  // ...
});

result.toDataStream();
result.pipeDataStreamToResponse(response);
result.toDataStreamResponse();
```
